if marker not in text:
    anchor = "function finalShiftReportHtml()"
    pos = text.find(anchor)
    if pos < 0:
        raise SystemExit("Could not locate finalShiftReportHtml anchor")
    text = text[:pos] + helper + text[pos:]

def replace_line(text, prefix, replacement):
    pattern = re.compile(r"^" + re.escape(prefix) + r".*$", re.M)
    matches = list(pattern.finditer(text))
    if len(matches) != 1:
        raise SystemExit(f"Expected one {prefix} line, found {len(matches)}")
    m = matches[0]
    return text[:m.start()] + replacement + text[m.end():]

text = replace_line(text, "function finalShiftReportHtml()", final_line)
